ALTER TABLE parties ADD COLUMN kpp VARCHAR(20) NULL, ADD COLUMN legal_address TEXT NULL, ADD COLUMN postal_address TEXT NULL, ADD COLUMN postal_same_as_legal BOOLEAN NULL, ADD COLUMN additional_contact VARCHAR(255) NULL, ADD COLUMN additional_phone VARCHAR(100) NULL, ADD COLUMN document_recipient VARCHAR(255) NULL, ADD COLUMN additional_document_recipient VARCHAR(255) NULL, ADD COLUMN edo VARCHAR(255) NULL, ADD COLUMN edo_id VARCHAR(255) NULL, ADD COLUMN description TEXT NULL;
UPDATE parties SET kpp=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.kpp')),'null'),legal_address=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.legalAddress')),'null'),postal_address=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.postalAddress')),'null'),postal_same_as_legal=CASE JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.postalSameAsLegal')) WHEN 'true' THEN 1 WHEN 'false' THEN 0 ELSE NULL END,additional_contact=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.additionalContact')),'null'),additional_phone=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.additionalPhone')),'null'),document_recipient=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.documentRecipient')),'null'),additional_document_recipient=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.additionalDocumentRecipient')),'null'),edo=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.edo')),'null'),edo_id=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.edoId')),'null'),description=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.description')),'null');
ALTER TABLE organization ADD COLUMN ogrnip VARCHAR(30) NULL, ADD COLUMN contact VARCHAR(255) NULL, ADD COLUMN phone VARCHAR(100) NULL, ADD COLUMN postal_address TEXT NULL, ADD COLUMN postal_same_as_legal BOOLEAN NULL, ADD COLUMN edo VARCHAR(255) NULL, ADD COLUMN edo_id VARCHAR(255) NULL;
UPDATE organization SET ogrnip=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.ogrnip')),'null'),contact=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.contact')),'null'),phone=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.phone')),'null'),postal_address=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.postalAddress')),'null'),postal_same_as_legal=CASE JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.postalSameAsLegal')) WHEN 'true' THEN 1 WHEN 'false' THEN 0 ELSE NULL END,edo=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.edo')),'null'),edo_id=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.edoId')),'null');
ALTER TABLE invoices ADD COLUMN title TEXT NULL, ADD COLUMN purpose TEXT NULL, ADD COLUMN vat DECIMAL(8,4) NULL, ADD COLUMN payer_snapshot JSON NULL, ADD COLUMN payee_snapshot JSON NULL;
UPDATE invoices SET title=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.title')),'null'),purpose=NULLIF(JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.purpose')),'null'),vat=CASE WHEN JSON_TYPE(JSON_EXTRACT(source_json,'$.vat')) IN ('INTEGER','DOUBLE') THEN JSON_UNQUOTE(JSON_EXTRACT(source_json,'$.vat')) ELSE NULL END,payer_snapshot=JSON_EXTRACT(source_json,'$.payerSnapshot'),payee_snapshot=JSON_EXTRACT(source_json,'$.payeeSnapshot');
ALTER TABLE payments ADD COLUMN source_filename VARCHAR(255) NULL, ADD COLUMN entered_by VARCHAR(255) NULL;
CREATE TABLE IF NOT EXISTS rental_payment_versions (payment_id BIGINT NOT NULL, version INT NOT NULL, amount DECIMAL(20,2) NOT NULL, payment_date DATE NULL, actor_id BIGINT UNSIGNED NOT NULL, recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(payment_id,version), FOREIGN KEY(payment_id) REFERENCES payments(id));
CREATE TABLE IF NOT EXISTS rental_field_overrides (entity_type VARCHAR(30) NOT NULL, entity_id BIGINT NOT NULL, field_name VARCHAR(80) NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(entity_type,entity_id,field_name));
